import sys
import re
import os
import time
from datetime import datetime

def parse_input():
    variables = {}
    for line in sys.stdin:
        stripped = line.strip()
        if stripped:
            name, value = stripped.split('=', 1)
            variables[name] = value
    return variables

def parse_template(template_path):
    with open(template_path, 'r', encoding='utf-8') as f:
        return f.read()

def evaluate_expression(expr, variables):
    try:
        # Replace variables with their values and evaluate
        for name in variables:
            expr = expr.replace(name, str(variables[name]))
        # Evaluate the expression safely
        return eval(expr)
    except Exception as e:
        raise ValueError(f"Evaluation error: {str(e)}")

def render_template(template, variables):
    result = []
    log_entries = []
    timestamp = datetime.utcnow().isoformat() + 'Z'
    placeholder_pattern = re.compile(r'\{\{([^}]+)\}\}')

    for line in template.splitlines():
        for match in placeholder_pattern.finditer(line):
            placeholder_text = match.group(0)
            expr = match.group(1).strip()
            try:
                value = evaluate_expression(expr, variables)
                rendered_line = line[:match.start()] + str(value) + line[match.end():]
                result.append(rendered_line)
                log_entries.append(f"{timestamp} {placeholder_text} {value}")
            except ValueError as e:
                rendered_line = line
                log_entries.append(f"{timestamp} {placeholder_text} ERROR {str(e)}")
                result.append(rendered_line)
    return '\n'.join(result), log_entries

def write_log(log_entries):
    with open('render.log', 'w', encoding='utf-8') as f:
        for entry in log_entries:
            f.write(entry + '\n')

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    template_path = sys.argv[1]
    variables = parse_input()
    template = parse_template(template_path)
    rendered, log_entries = render_template(template, variables)
    print(rendered)
    write_log(log_entries)

if __name__ == "__main__":
    main()

import argparse
import sys
import re
from datetime import datetime
import os

def parse_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument('template', type=str, help='Path to the UTF-8 template file')
    return parser.parse_args()

def read_variables():
    variables = {}
    for line in sys.stdin:
        stripped = line.strip()
        if not stripped:
            continue
        if '=' not in stripped:
            continue
        name, value = stripped.split('=', 1)
        variables[name] = value
    return variables

def evaluate_expression(expr, variables):
    try:
        # Replace variables with their values
        for name, value in variables.items():
            if value.startswith('-'):
                value = value[1:]
                value = int(value)
            else:
                value = int(value)
            expr = expr.replace(name, str(value))
        # Evaluate the expression
        result = eval(expr)
        return str(result)
    except Exception as e:
        return f"ERROR {str(e)}"

def render_template(template_path, variables):
    with open(template_path, 'r', encoding='utf-8') as f:
        content = f.read()

    placeholder_pattern = re.compile(r'\{\{([^}]+)\}\}')
    placeholders = placeholder_pattern.findall(content)

    rendered_content = content
    for placeholder in placeholders:
        # Extract the expression from the placeholder
        expr = placeholder.strip()
        result = evaluate_expression(expr, variables)

        # Log the result
        timestamp = datetime.utcnow().isoformat(timespec='seconds') + 'Z'
        log_entry = f"{timestamp} {placeholder} {result}\n"
        with open('render.log', 'a', encoding='utf-8') as log_file:
            log_file.write(log_entry)

        # Replace the placeholder with the result
        rendered_content = rendered_content.replace(f'{{{{{placeholder}}}}}', result)

    return rendered_content

def main():
    args = parse_arguments()
    variables = read_variables()
    rendered_content = render_template(args.template, variables)
    print(rendered_content)

if __name__ == '__main__':
