import sys
import re
import os
from pathlib import Path

def parse_argv():
    if len(sys.argv) != 2:
        sys.exit(1)
    return sys.argv[1]

def read_variables():
    variables = {}
    for line in sys.stdin:
        stripped = line.strip()
        if not stripped:
            continue
        name, value = stripped.split('=', 1)
        try:
            variables[name] = int(value)
        except ValueError:
            continue
    return variables

def evaluate_expression(expr, variables):
    try:
        # Replace variable names with their values
        for name, val in variables.items():
            expr = expr.replace(name, str(val))
        # Evaluate the arithmetic expression
        result = eval(expr)
        return str(result)
    except Exception as e:
        return f"ERROR {str(e)}"

def render_template(template_path, variables):
    with open(template_path, 'r', encoding='utf-8') as f:
        template = f.read()

    # Find all placeholders in the template
    placeholders = re.findall(r'\{\{([^}]+)\}\}', template)
    rendered_parts = []
    log_entries = []

    for placeholder in placeholders:
        # Evaluate the expression inside the placeholder
        result = evaluate_expression(placeholder, variables)
        log_entries.append(f"{placeholder} -> {result}")
        rendered_parts.append(result)

    # Replace placeholders in the template
    rendered_template = template
    for i, placeholder in enumerate(placeholders):
        rendered_template = rendered_template.replace(f"{{{{{placeholder}}}}}", rendered_parts[i])

    # Write log entries
    with open('render.log', 'w', encoding='utf-8') as log_file:
        log_file.write('\n'.join(log_entries))

    return rendered_template

def main():
    template_path = parse_argv()
    variables = read_variables()
    rendered = render_template(template_path, variables)
    print(rendered)

if __name__ == "__main__":
    main()
